-- V-404 / MySQL 8+ ve MariaDB 10.4+ / Yeni, boş veritabanına bir kez aktarın.
CREATE DATABASE IF NOT EXISTS v404 CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE v404;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL, role ENUM('user','admin','moderator') NOT NULL DEFAULT 'user',
 verified TINYINT NOT NULL DEFAULT 0, adult TINYINT NOT NULL DEFAULT 1, notifications TINYINT NOT NULL DEFAULT 1,
 status ENUM('active','restricted','closed') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS verifications (user_id BIGINT UNSIGNED PRIMARY KEY, code_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, attempts INT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS organizations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, kind VARCHAR(40) NOT NULL, city VARCHAR(80) NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS locations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, org_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED NULL, name VARCHAR(100) NOT NULL, kind ENUM('branch','building','floor','room') NOT NULL, FOREIGN KEY(org_id) REFERENCES organizations(id), FOREIGN KEY(parent_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS memberships (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, org_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, role ENUM('member','staff','location_admin','org_admin') NOT NULL DEFAULT 'member', location_id BIGINT UNSIGNED NULL, status ENUM('pending','approved') NOT NULL DEFAULT 'pending', UNIQUE KEY membership(org_id,user_id), FOREIGN KEY(org_id) REFERENCES organizations(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(location_id) REFERENCES locations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS invites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, org_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listings (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL,
 type ENUM('lost','found','free','pet_lost','pet_found','adoption') NOT NULL,
 title VARCHAR(120) NOT NULL, category VARCHAR(80) NOT NULL, description TEXT NOT NULL, city VARCHAR(80) NOT NULL, district VARCHAR(100) NOT NULL,
 event_date DATE NOT NULL, color VARCHAR(60) NOT NULL DEFAULT '', brand VARCHAR(80) NOT NULL DEFAULT '', model VARCHAR(80) NOT NULL DEFAULT '',
 secret TEXT NOT NULL, route TEXT NOT NULL, latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, route_points TEXT NULL, custody VARCHAR(120) NOT NULL DEFAULT '', private_location TEXT NOT NULL,
 condition_text TEXT NOT NULL, health TEXT NOT NULL,
 org_id BIGINT UNSIGNED NULL, location_id BIGINT UNSIGNED NULL, visibility ENUM('public','org','both') NOT NULL DEFAULT 'public',
 status ENUM('open','reserved','delivered','closed','archived','hidden','deleted') NOT NULL DEFAULT 'open', alert TINYINT NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, closed_at DATETIME NULL,
 INDEX search_idx(status,type,city,category), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(org_id) REFERENCES organizations(id), FOREIGN KEY(location_id) REFERENCES locations(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS photos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NULL, ticket_id BIGINT UNSIGNED NULL, user_id BIGINT UNSIGNED NOT NULL, path VARCHAR(100) NOT NULL, mime VARCHAR(40) NOT NULL, FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS matches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lost_id BIGINT UNSIGNED NOT NULL, found_id BIGINT UNSIGNED NOT NULL, score INT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY pair(lost_id,found_id), FOREIGN KEY(lost_id) REFERENCES listings(id), FOREIGN KEY(found_id) REFERENCES listings(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS claims (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, listing_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, proof TEXT NOT NULL, status ENUM('pending','accepted','rejected','delivered') NOT NULL DEFAULT 'pending', owner_confirm TINYINT NOT NULL DEFAULT 0, claimant_confirm TINYINT NOT NULL DEFAULT 0, chat_closed TINYINT NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY claimant(listing_id,user_id), FOREIGN KEY(listing_id) REFERENCES listings(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, claim_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(claim_id) REFERENCES claims(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, listing_id BIGINT UNSIGNED NULL, is_read TINYINT NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS blocks (user_id BIGINT UNSIGNED NOT NULL, target_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,target_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(target_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, target_type ENUM('listing','user','chat') NOT NULL, target_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(100) NOT NULL, body TEXT NOT NULL, status ENUM('open','reviewing','resolved') NOT NULL DEFAULT 'open', reply TEXT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, subject VARCHAR(120) NOT NULL, body TEXT NOT NULL, status ENUM('open','reviewing','resolved') NOT NULL DEFAULT 'open', reply TEXT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, action VARCHAR(100) NOT NULL, target_id BIGINT UNSIGNED NULL, detail TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB;
INSERT IGNORE INTO settings VALUES ('announcement',''),('registration_open','1');
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, reset_at BIGINT NOT NULL) ENGINE=InnoDB;
